#include <iostream>

class IntBuffer {
public:
    explicit IntBuffer(int size) : size_(size), data_(new int[size]()) {}

    IntBuffer(const IntBuffer& other) : size_(other.size_), data_(new int[other.size_]) {
        for (int i = 0; i < size_; ++i) {
            data_[i] = other.data_[i];
        }
        std::cout << "copied " << size_ << " ints\n";
    }

    IntBuffer& operator=(const IntBuffer& other) {
        if (this != &other) {
            delete[] data_;
            size_ = other.size_;
            data_ = new int[size_];
            for (int i = 0; i < size_; ++i) {
                data_[i] = other.data_[i];
            }
            std::cout << "assigned " << size_ << " ints\n";
        }
        return *this;
    }

    ~IntBuffer() {
        delete[] data_;
        std::cout << "freed " << size_ << " ints\n";
    }

    int get(int i) const {
        return data_[i];
    }

    void set(int i, int value) {
        data_[i] = value;
    }

private:
    int size_;
    int* data_;
};

int main() {
    IntBuffer original(5);
    for (int i = 0; i < 5; ++i) {
        original.set(i, i + 1);
    }
    IntBuffer copy = original;
    copy.set(0, 99);
    std::cout << original.get(0) << ' ' << copy.get(0) << '\n';
    IntBuffer third(2);
    third = original;
    std::cout << third.get(0) << '\n';
    return 0;
}

