#include <iostream>
#include <utility>
#include <vector>

class IntBuffer {
public:
    explicit IntBuffer(int size) : size_(size), data_(new int[size]()) {}

    // Copies from step 1 are left out to keep this short.
    IntBuffer(const IntBuffer&) = delete;
    IntBuffer& operator=(const IntBuffer&) = delete;

    IntBuffer(IntBuffer&& other) noexcept : size_(other.size_), data_(other.data_) {
        other.size_ = 0;
        other.data_ = nullptr;
        std::cout << "moved " << size_ << " ints\n";
    }

    IntBuffer& operator=(IntBuffer&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            size_ = other.size_;
            data_ = other.data_;
            other.size_ = 0;
            other.data_ = nullptr;
            std::cout << "move-assigned " << size_ << " ints\n";
        }
        return *this;
    }

    ~IntBuffer() {
        delete[] data_;
        std::cout << "freed " << size_ << " ints\n";
    }

    int size() const {
        return size_;
    }

private:
    int size_;
    int* data_;
};

int main() {
    IntBuffer a(5);
    IntBuffer b = std::move(a);
    std::cout << a.size() << ' ' << b.size() << '\n';
    IntBuffer c(2);
    c = std::move(b);
    std::cout << b.size() << ' ' << c.size() << '\n';

    std::vector<int> source = {4, 8, 15};
    std::vector<int> target = std::move(source);
    source = {16, 23};
    std::cout << target.size() << ' ' << target.capacity() << ' ' << source.size() << '\n';
    return 0;
}

